#include <iostream>
class X {
public:
  static void f();
  void f(); // ill-formed: cannot overload static and non-static f with same signature
  void g();
  void g() const; // OK: Overloading non-static g is allowed
};
void X::f() {}
void X::g() {}
void X::g() const {}
int main() {
  X x;
  //x.f(); //This would result in a compiler error if uncommented
  x.g();
  return 0;
}
